import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

export type LinkStore = {
  get(code: string): string | undefined;
  set(code: string, url: string): void;
};

// Links live in a JSON file as { [code]: url }. Sync I/O keeps each
// read-modify-write in one tick, so concurrent requests can't lose writes.
export function createFileStore(filePath: string): LinkStore {
  const read = (): Record<string, string> =>
    existsSync(filePath) ? JSON.parse(readFileSync(filePath, "utf8")) : {};

  return {
    get(code) {
      const links = read();
      return Object.hasOwn(links, code) ? links[code] : undefined;
    },
    set(code, url) {
      const links = read();
      links[code] = url;
      mkdirSync(dirname(filePath), { recursive: true });
      writeFileSync(filePath, JSON.stringify(links, null, 2));
    },
  };
}

import { Hono } from "hono";
import { zValidator } from "@hono/zod-validator";
import { nanoid } from "nanoid";
import { z } from "zod";
import type { LinkStore } from "./store.js";

const createLinkSchema = z.object({
  url: z.url({ protocol: /^https?$/ }),
});

export function createApp(store: LinkStore) {
  const app = new Hono();

  app.post("/links", zValidator("json", createLinkSchema), (c) => {
    const { url } = c.req.valid("json");
    let code: string;
    do {
      code = nanoid(8);
    } while (store.get(code) !== undefined);
    store.set(code, url);
    return c.json({ code }, 201);
  });

  app.get("/:code", (c) => {
    const url = store.get(c.req.param("code"));
    if (url === undefined) {
      return c.json({ error: "Not found" }, 404);
    }
    return c.redirect(url, 302);
  });

  return app;
}

import { serve } from "@hono/node-server";
import { createApp } from "./app.js";
import { createFileStore } from "./store.js";

const port = Number(process.env.PORT ?? 3000);
const dataFile = process.env.LINKS_FILE ?? "data/links.json";

const app = createApp(createFileStore(dataFile));

serve({ fetch: app.fetch, port }, (info) => {
  console.log(`linkshort listening on http://localhost:${info.port}`);
});

import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../src/app.js";
import { createFileStore } from "../src/store.js";

// Temp files stay inside the project folder.
let tmpDir: string;
let dataFile: string;

beforeEach(() => {
  tmpDir = mkdtempSync(join(import.meta.dirname, ".tmp-"));
  dataFile = join(tmpDir, "links.json");
});

afterEach(() => {
  rmSync(tmpDir, { recursive: true, force: true });
});

function postLink(app: ReturnType<typeof createApp>, body: unknown) {
  return app.request("/links", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
}

describe("POST /links", () => {
  it("returns a short code and saves the link to the JSON file", async () => {
    const app = createApp(createFileStore(dataFile));

    const res = await postLink(app, { url: "https://example.com/some/page?x=1" });

    expect(res.status).toBe(201);
    const { code } = await res.json();
    expect(code).toMatch(/^[A-Za-z0-9_-]{8}$/);
    expect(JSON.parse(readFileSync(dataFile, "utf8"))).toEqual({
      [code]: "https://example.com/some/page?x=1",
    });
  });

  it("gives different codes for different links", async () => {
    const app = createApp(createFileStore(dataFile));

    const a = await (await postLink(app, { url: "https://a.example" })).json();
    const b = await (await postLink(app, { url: "https://b.example" })).json();

    expect(a.code).not.toBe(b.code);
  });

  it.each([
    ["a missing url", {}],
    ["a non-string url", { url: 42 }],
    ["text that is not a url", { url: "not a url" }],
    ["a non-http url", { url: "javascript:alert(1)" }],
  ])("rejects %s with 400", async (_label, body) => {
    const app = createApp(createFileStore(dataFile));

    const res = await postLink(app, body);

    expect(res.status).toBe(400);
  });
});

describe("GET /:code", () => {
  it("redirects to the saved URL", async () => {
    const app = createApp(createFileStore(dataFile));
    const { code } = await (await postLink(app, { url: "https://example.com/target" })).json();

    const res = await app.request(`/${code}`);

    expect(res.status).toBe(302);
    expect(res.headers.get("Location")).toBe("https://example.com/target");
  });

  it("still redirects after a restart, reading from the JSON file", async () => {
    const first = createApp(createFileStore(dataFile));
    const { code } = await (await postLink(first, { url: "https://example.com/kept" })).json();

    const second = createApp(createFileStore(dataFile));
    const res = await second.request(`/${code}`);

    expect(res.status).toBe(302);
    expect(res.headers.get("Location")).toBe("https://example.com/kept");
  });

  it("returns 404 for an unknown code", async () => {
    const app = createApp(createFileStore(dataFile));

    const res = await app.request("/nope1234");

    expect(res.status).toBe(404);
  });

  it("returns 404 for codes that match built-in object keys", async () => {
    const app = createApp(createFileStore(dataFile));
    await postLink(app, { url: "https://example.com" });

    const res = await app.request("/constructor");

    expect(res.status).toBe(404);
  });
});

